type Tab = "surveys" | "tracking" | "marketing";
type TrackingMode = "brand" | "store";
type Filter = "template" | "cycle" | "brand" | "region" | "store" | null;
type Palette = ReturnType<typeof useColors>;
type NoteStyle = { label: string; color: string; icon: keyof typeof MaterialIcons.glyphMap };

const NOTE_STYLES: Record<TrackingNote["type"], NoteStyle> = {
  positive: { label: "إيجابي", color: "#16A34A", icon: "thumb-up" },
  negative: { label: "سلبي", color: "#EA580C", icon: "thumb-down" },
  complaint: { label: "شكوى", color: "#DC2626", icon: "report-problem" },
  suggestion: { label: "اقتراح", color: "#2563EB", icon: "lightbulb" },
  recommendation: { label: "تزكية", color: "#7C3AED", icon: "workspace-premium" },
};

function selectionLabel(values: string[], allLabel: string): string {
  if (!values.length) return allLabel;
  if (values.length === 1) return values[0];
  return `${values.length} مختارة`;
}

export function AdvancedAnalyticsModule({ externalPackageId, combinedExternal, onBack }: { externalPackageId?: string; combinedExternal?: boolean; onBack?: () => void }) {
  const colors = useColors();
  const canCreate = useHasPermission("analytics", "create");
  const canDelete = useHasPermission("analytics", "delete");
  const canExport = useHasPermission("analytics", "export");
  const canManage = useHasPermission("analytics", "manage");
  const [tab, setTab] = useState<Tab>("surveys");
  const [menuOpen, setMenuOpen] = useState(false);
  const [filter, setFilter] = useState<Filter>(null);
  const [showSettings, setShowSettings] = useState(false);
  const [showScope, setShowScope] = useState(false);
  const [showProductScope, setShowProductScope] = useState(false);
  const [exporting, setExporting] = useState<"pdf" | "excel" | null>(null);
  const [settings, setSettings] = useState<AnalyticsSettings>(DEFAULT_ANALYTICS_SETTINGS);
  const [templates, setTemplates] = useState<SurveyTemplate[]>([]);
  const [results, setResults] = useState<SurveyResult[]>([]);
  const [cycles, setCycles] = useState<SurveyCycle[]>([]);
  const [stores, setStores] = useState<Store[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [events, setEvents] = useState<MarketingEventRecord[]>([]);
  const [signages, setSignages] = useState<MarketingSignageRecord[]>([]);
  const [stands, setStands] = useState<MarketingStandRecord[]>([]);
  const [goals, setGoals] = useState<MarketingGoalRecord[]>([]);
  const [catalogBrandNames, setCatalogBrandNames] = useState<string[]>([]);
  const [catalogRegionNames, setCatalogRegionNames] = useState<string[]>([]);
  const [templateId, setTemplateId] = useState("");
  const [cycleId, setCycleId] = useState("all");
  const [brand, setBrand] = useState("");
  const [region, setRegion] = useState("");
  const [storeId, setStoreId] = useState("");
  const [trackingMode, setTrackingMode] = useState<TrackingMode>("brand");
  const [productIds, setProductIds] = useState<string[]>([]);
  const [matrixRegionNames, setMatrixRegionNames] = useState<string[]>([]);
  const [matrixProductIds, setMatrixProductIds] = useState<string[]>([]);
  const [marketingBrands, setMarketingBrands] = useState<string[]>([]);
  const [marketingRegions, setMarketingRegions] = useState<string[]>([]);
  const [showExternalImport, setShowExternalImport] = useState(false);
  const [showExternalPackages, setShowExternalPackages] = useState(false);
  const [externalPackages, setExternalPackages] = useState<ExternalAnalyticsPackage[]>([]);
  const [externalPayload, setExternalPayload] = useState<SurveyResultsExportPayload | null>(null);
  const [externalPackageName, setExternalPackageName] = useState("");
  const [externalFileName, setExternalFileName] = useState("");
  const [importingExternal, setImportingExternal] = useState(false);
  const [externalPackageTitle, setExternalPackageTitle] = useState("");
  const [packageToDelete, setPackageToDelete] = useState<ExternalAnalyticsPackage | null>(null);

  const reload = useCallback(async () => {
    if (combinedExternal) {
      const [savedSettings, dataset] = await Promise.all([loadAnalyticsSettings(), buildCombinedExternalAnalyticsDataset()]);
      setExternalPackageTitle("تحليل الاستبيانات المحفوظة"); setTemplates([dataset.template]); setResults(dataset.results); setCycles(dataset.cycles); setStores(dataset.stores); setProducts(dataset.products); setEvents([]); setSignages([]); setStands([]); setGoals([]); setCatalogBrandNames([]); setCatalogRegionNames([]); setSettings(savedSettings); setTemplateId(dataset.template.id);
      return;
    }
    if (externalPackageId) {
      const [savedPackage, savedSettings] = await Promise.all([getExternalAnalyticsPackage(externalPackageId), loadAnalyticsSettings()]);
      if (!savedPackage) { setExternalPackageTitle("حزمة غير متاحة"); setTemplates([]); setResults([]); setCycles([]); setStores([]); setProducts([]); setSettings(savedSettings); return; }
      const { dataset } = savedPackage;
      setExternalPackageTitle(savedPackage.name); setTemplates([dataset.template]); setResults(dataset.results); setCycles(dataset.cycles); setStores(dataset.stores); setProducts(dataset.products); setEvents([]); setSignages([]); setStands([]); setGoals([]); setCatalogBrandNames([]); setCatalogRegionNames([]); setSettings(savedSettings); setTemplateId(dataset.template.id);
      return;
    }
    const [savedTemplates, savedResults, savedCycles, savedStores, savedProducts, savedEvents, savedSignages, savedStands, savedGoals, catalog, savedSettings] = await Promise.all([
      getItems<SurveyTemplate>(STORAGE_KEYS.SURVEY_TEMPLATES), getItems<SurveyResult>(STORAGE_KEYS.SURVEY_RESULTS), getItems<SurveyCycle>(STORAGE_KEYS.SURVEY_CYCLES), getItems<Store>(STORAGE_KEYS.STORES), getItems<Product>(STORAGE_KEYS.PRODUCTS), getItems<MarketingEventRecord>(STORAGE_KEYS.EVENTS), getItems<MarketingSignageRecord>(STORAGE_KEYS.SIGNAGE_BOARDS), getItems<MarketingStandRecord>(STORAGE_KEYS.STANDS), getItems<MarketingGoalRecord>(STORAGE_KEYS.MARKETING_GOALS), loadBrandRegionCatalog(), loadAnalyticsSettings(),
    ]);
    const surveyData = pruneOrphanedSurveyData(savedTemplates, savedResults, savedCycles);
    setTemplates(surveyData.templates); setResults(surveyData.results); setCycles(surveyData.cycles); setStores(savedStores.filter((store) => store.isActive)); setProducts(savedProducts); setEvents(savedEvents); setSignages(savedSignages); setStands(savedStands); setGoals(savedGoals);
    setCatalogBrandNames(catalog.brands.filter((item) => item.isActive).map((item) => item.name));
    setCatalogRegionNames(catalog.regions.filter((item) => item.isActive).map((item) => item.name)); setSettings(savedSettings);
    setTemplateId((current) => current || surveyData.templates[0]?.id || surveyData.results[0]?.templateId || "");
  }, [combinedExternal, externalPackageId]);

  useEffect(() => { void reload(); }, [reload]);

  const template = templates.find((item) => item.id === templateId);
  const templateProductIds = useMemo(() => template?.products.map((product) => product.productId) || [], [template]);
  const templateCategoryOrder = useMemo(() => {
    const categoryByProductId = new Map(products.map((product) => [product.id, product.categoryName?.trim() || "بدون تصنيف"]));
    return orderAnalyticsCategories((template?.products || []).map((product) => product.category?.trim() || categoryByProductId.get(product.productId) || "بدون تصنيف"));
  }, [products, template]);
  const templateResults = useMemo(() => results.filter((item) => !templateId || item.templateId === templateId), [results, templateId]);
  const templateCycles = useMemo(() => cycles.filter((item) => !templateId || item.templateId === templateId), [cycles, templateId]);
  const allProductOptions = useMemo(() => getAnalyticsProductOptions(templateResults, products, templateId, templateProductIds), [products, templateId, templateProductIds, templateResults]);
  const brands = useMemo(() => Array.from(new Set([...catalogBrandNames, ...allProductOptions.map((item) => item.brandName).filter((value): value is string => Boolean(value))])).sort((first, second) => first.localeCompare(second, "ar")), [allProductOptions, catalogBrandNames]);
  const regions = useMemo(() => Array.from(new Set([...catalogRegionNames, ...stores.map((store) => store.region).filter(Boolean)])).sort((first, second) => first.localeCompare(second, "ar")), [catalogRegionNames, stores]);
  const availableStores = useMemo(() => stores.filter((store) => !region || store.region === region), [region, stores]);
  const visibleProducts = useMemo(() => allProductOptions.filter((item) => !brand || item.brandName === brand), [allProductOptions, brand]);
  const filters = useMemo<AdvancedAnalyticsFilters>(() => ({ templateId: templateId || undefined, cycleIds: cycleId === "all" ? undefined : [cycleId], productIds: productIds.length ? productIds : undefined, brandName: brand || undefined, regionName: region || undefined, storeIds: storeId ? [storeId] : undefined }), [brand, cycleId, productIds, region, storeId, templateId]);
  const analytics = useMemo<AdvancedSurveyAnalytics>(() => calculateCyclePresenceSeries(results, stores, products, cycles, filters, templateProductIds), [cycles, filters, products, results, stores, templateProductIds]);
  const filteredSurveyResults = useMemo(() => filterAdvancedSurveyResults(results, stores, products, filters), [filters, products, results, stores]);
  const decisionMetrics = useMemo(() => calculateAnalyticsDecisionMetrics(analytics, filteredSurveyResults, stores, filters, settings), [analytics, filteredSurveyResults, filters, settings, stores]);
  const displayAnalytics = useMemo(() => sortAnalyticsProducts(analytics, settings.productSort), [analytics, settings.productSort]);
  const matrixRegionOptions = useMemo(() => Array.from(new Set(filteredSurveyResults.map((result) => result.storeRegion.trim() || "غير محددة"))).sort((first, second) => first.localeCompare(second, "ar")), [filteredSurveyResults]);
  const regionMatrix = useMemo(() => buildRegionProductMatrix(filteredSurveyResults, displayAnalytics.productOptions, settings.regionMatrix, settings.presenceBasis, { regionNames: matrixRegionNames, productIds: matrixProductIds }), [displayAnalytics.productOptions, filteredSurveyResults, matrixProductIds, matrixRegionNames, settings.presenceBasis, settings.regionMatrix]);
  const matrixCategoryOptions = useMemo(() => orderAnalyticsCategories(displayAnalytics.productOptions.map((product) => product.category?.trim() || "غير مصنف"), templateCategoryOrder), [displayAnalytics.productOptions, templateCategoryOrder]);
  const categoryMatrices = useMemo(() => {
    if (!settings.regionMatrix.categoryMatricesEnabled || !settings.regionMatrix.categoryMatrixCategoryNames.length) return [];
    const orderedCategoryNames = orderAnalyticsCategories(settings.regionMatrix.categoryMatrixCategoryNames, templateCategoryOrder);
    return orderedCategoryNames.flatMap((category) => {
      const categoryProducts = displayAnalytics.productOptions.filter((product) => (product.category?.trim() || "غير مصنف") === category);
      const selectedCategoryProductIds = matrixProductIds.length ? matrixProductIds.filter((id) => categoryProducts.some((product) => product.id === id)) : [];
      if (!categoryProducts.length || (matrixProductIds.length && !selectedCategoryProductIds.length)) return [];
      const matrix = buildRegionProductMatrix(filteredSurveyResults, categoryProducts, settings.regionMatrix, settings.presenceBasis, { regionNames: matrixRegionNames, productIds: selectedCategoryProductIds.length ? selectedCategoryProductIds : undefined });
      return matrix.regions.length && matrix.products.length ? [{ category, matrix, products: categoryProducts, selectedProductIds: selectedCategoryProductIds }] : [];
    });
  }, [displayAnalytics.productOptions, filteredSurveyResults, matrixProductIds, matrixRegionNames, settings.presenceBasis, settings.regionMatrix, templateCategoryOrder]);
  const sourcePresence = useMemo(() => calculateAnalyticsSourcePresenceAverages(displayAnalytics, settings.presenceBasis === "uniqueStores" ? decisionMetrics.uniqueStorePresence : undefined), [decisionMetrics.uniqueStorePresence, displayAnalytics, settings.presenceBasis]);
  const marketing = useMemo(() => calculateMarketingAnalytics(events, signages, stands, stores, { brandNames: marketingBrands.length ? marketingBrands : undefined, regionNames: marketingRegions.length ? marketingRegions : undefined }, goals), [events, goals, marketingBrands, marketingRegions, signages, stands, stores]);
  const trackingMarketing = useMemo(() => calculateMarketingAnalytics(events, signages, stands, stores, trackingMode === "brand" ? { brandName: brand || undefined } : { storeId: storeId || undefined }, goals), [brand, events, goals, signages, stands, storeId, stores, trackingMode]);
  const trackingProfile = useMemo(() => trackingMode === "brand" ? buildBrandTrackingProfile(brand || "اختر ماركة", displayAnalytics, trackingMarketing) : buildStoreTrackingProfile(stores.find((store) => store.id === storeId)?.name || "اختر محلاً", displayAnalytics, trackingMarketing), [brand, displayAnalytics, storeId, stores, trackingMarketing, trackingMode]);
  const selectedCycle = templateCycles.find((item) => item.id === cycleId);
  const scopeLabel = `${trackingMode === "brand" ? `الماركة: ${brand || "كل الماركات"}` : storeId ? `المحل: ${stores.find((store) => store.id === storeId)?.name || "غير متاح"}` : "كل المحلات"} · ${cycleId === "all" ? "كل الدورات" : selectedCycle?.name || "دورة محددة"}`;
  const activeBrandLabel = tab === "marketing" ? selectionLabel(marketingBrands, "كل الماركات") : brand || "كل الماركات";
  const activeRegionLabel = tab === "marketing" ? selectionLabel(marketingRegions, "كل المناطق") : region || "كل المناطق";
  const report = useMemo(() => buildAnalyticsReportData(displayAnalytics, {
    analysisName: tab === "tracking" ? trackingMode === "brand" ? "تتبع ماركة" : "تتبع محل" : tab === "marketing" ? "الفعاليات واللوحات والستاندات" : "تواجد الاستبيانات والدورات",
    reportTitle: tab === "tracking" ? trackingMode === "brand" ? "تقرير تتبع الماركة" : "تقرير تتبع المحل" : tab === "marketing" ? "تقرير الفعاليات واللوحات" : "تقرير الاستبيانات والدورات",
    templateName: template?.name || "كل الاستبيانات", cycleName: cycleId === "all" ? "كل الدورات" : selectedCycle?.name || "دورة محددة", brandName: activeBrandLabel, regionName: activeRegionLabel, storeName: tab === "marketing" ? "النطاق التسويقي" : storeId ? stores.find((store) => store.id === storeId)?.name || "محل محدد" : "كل المحلات",
    reportPurpose: settings.reportPurpose === "field" ? "تفصيلي ميداني" : settings.reportPurpose === "comparison" ? "مقارنة دورات" : "تنفيذي",
    presenceBasis: settings.presenceBasis === "uniqueStores" ? "محلات فريدة" : "زيارات ميدانية",
    comparisonReference: settings.comparisonReference === "none" ? "بدون مقارنة" : settings.comparisonReference === "firstInRange" ? "أول دورة في النطاق" : "الدورة السابقة",
  }, tab === "surveys" ? undefined : tab === "tracking" ? trackingMarketing : marketing, { stores, results, filters }, { settings, decisionMetrics: tab === "surveys" || tab === "tracking" ? decisionMetrics : undefined, ...(tab === "surveys" ? settings.regionMatrix.categoryMatricesEnabled ? { categoryMatrices: categoryMatrices.map((item) => ({ category: item.category, matrix: item.matrix })) } : { regionMatrix } : {}) }), [activeBrandLabel, activeRegionLabel, categoryMatrices, cycleId, decisionMetrics, displayAnalytics, filters, marketing, regionMatrix, results, selectedCycle?.name, settings, storeId, stores, tab, template?.name, trackingMarketing, trackingMode]);

  const resetTemplate = (id: string) => { setTemplateId(id); setCycleId("all"); setBrand(""); setRegion(""); setStoreId(""); setProductIds([]); setFilter(null); };
  const resetRegion = (value: string) => { setRegion(value); setStoreId(""); setFilter(null); };
  const toggleProduct = (id: string) => setProductIds((current) => current.includes(id) ? current.filter((value) => value !== id) : [...current, id]);
  const toggleProductCategory = (ids: string[]) => setProductIds((current) => ids.every((id) => current.includes(id)) ? current.filter((id) => !ids.includes(id)) : Array.from(new Set([...current, ...ids])));
  const toggleMarketingBrand = (value: string) => setMarketingBrands((current) => current.includes(value) ? current.filter((item) => item !== value) : [...current, value]);
  const toggleMarketingRegion = (value: string) => setMarketingRegions((current) => current.includes(value) ? current.filter((item) => item !== value) : [...current, value]);
  const toggleMatrixRegion = (value: string) => setMatrixRegionNames((current) => current.includes(value) ? current.filter((item) => item !== value) : [...current, value]);
  const toggleMatrixProduct = (value: string) => setMatrixProductIds((current) => current.includes(value) ? current.filter((item) => item !== value) : [...current, value]);
  const clearMarketingBrands = () => setMarketingBrands([]);
  const clearMarketingRegions = () => setMarketingRegions([]);
  const exportReport = async (format: "pdf" | "excel") => { setExporting(format); try { if (format === "pdf") await exportAdvancedAnalyticsPdf(report, displayAnalytics, settings); else await exportAdvancedAnalyticsExcel(report, settings); } finally { setExporting(null); setMenuOpen(false); } };
  const updateSettings = async (nextSettings: AnalyticsSettings) => { await saveAnalyticsSettings(nextSettings); setSettings(nextSettings); };
  const refreshExternalPackages = async () => setExternalPackages(await listExternalAnalyticsPackages());
  const openExternalPackages = async () => { await refreshExternalPackages(); setMenuOpen(false); setShowExternalPackages(true); };
  const chooseExternalFile = async () => {
    try {
      const response = await DocumentPicker.getDocumentAsync({ type: "application/json", copyToCacheDirectory: true, multiple: false });
      if (response.canceled || !response.assets?.[0]?.uri) return;
      const asset = response.assets[0];
      const payload = await readSurveyResultsFile(asset.uri);
      setExternalPayload(payload); setExternalFileName(asset.name || "ملف نتائج"); setExternalPackageName("");
    } catch (error) { Alert.alert("تعذر قراءة الملف", error instanceof Error ? error.message : "تعذر قراءة ملف نتائج الاستبيان."); }
  };
  const importExternalResults = async () => {
    if (!externalPayload) { Alert.alert("اختر ملفاً", "اختر ملف نتائج الاستبيان أولاً."); return; }
    setImportingExternal(true);
    try {
      const saved = await saveExternalAnalyticsPackage(externalPackageName, externalPayload);
      setShowExternalImport(false); setExternalPayload(null); setExternalFileName(""); await refreshExternalPackages();
      router.push({ pathname: "/external-analytics" as never, params: { packageId: saved.id } });
    } catch (error) { Alert.alert("تعذر حفظ التحليل", error instanceof Error ? error.message : "حدث خطأ أثناء حفظ الحزمة التحليلية."); }
    finally { setImportingExternal(false); }
  };
  const openExternalPackage = (item: ExternalAnalyticsPackage) => { setShowExternalPackages(false); router.push({ pathname: "/external-analytics" as never, params: { packageId: item.id } }); };
  const openCombinedExternalPackages = () => { setShowExternalPackages(false); router.push({ pathname: "/external-analytics" as never, params: { mode: "combined" } }); };
  const removeExternalPackage = async () => { if (!packageToDelete) return; try { await deleteExternalAnalyticsPackage(packageToDelete.id); await refreshExternalPackages(); setPackageToDelete(null); } catch (error) { Alert.alert("تعذر الحذف", error instanceof Error ? error.message : "تعذر حذف الحزمة التحليلية."); } };

  return <View style={[styles.root, { backgroundColor: colors.background }]}> 
    {externalPackageId || combinedExternal ? <View style={[styles.externalHeader, { borderColor: colors.border, backgroundColor: colors.surface }]}><TouchableOpacity onPress={onBack || (() => router.back())} style={[styles.externalBack, { backgroundColor: colors.background }]}><MaterialIcons name="arrow-forward" size={21} color={colors.foreground} /></TouchableOpacity><View style={styles.externalHeaderCopy}><Text style={[styles.externalHeaderTitle, { color: colors.foreground }]} numberOfLines={1}>{externalPackageTitle || "تحليل خارجي"}</Text><Text style={[styles.externalHeaderHint, { color: colors.muted }]}>{combinedExternal ? "آخر دورة من كل استبيان محفوظ" : "حزمة نتائج محفوظة ومعزولة"}</Text></View></View> : null}
    <View style={[styles.tabs, { backgroundColor: colors.surface, borderColor: colors.border }]}>{(["surveys", "tracking", "marketing"] as Tab[]).map((item) => <TouchableOpacity key={item} onPress={() => setTab(item)} style={[styles.tab, tab === item && { borderBottomColor: colors.primary }]}><Text style={[styles.tabText, { color: tab === item ? colors.primary : colors.muted }]}>{item === "surveys" ? "الاستبيانات والدورات" : item === "tracking" ? "تتبع ماركة أو محل" : "الفعاليات واللوحات"}</Text></TouchableOpacity>)}</View>
    <ScrollView contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>
      {tab === "tracking" ? <TrackingModeSelector mode={trackingMode} colors={colors} onChange={(mode) => { setTrackingMode(mode); if (mode === "brand") setStoreId(""); else { setBrand(""); setProductIds([]); } }} /> : null}
      <TouchableOpacity onPress={() => setShowScope(true)} style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={styles.titleRow}><Text style={[styles.title, { color: colors.foreground }]}>نطاق التحليل</Text><MaterialIcons name="tune" color={colors.primary} size={21} /></View><Text style={[styles.hint, { color: colors.muted }]}>{tab === "marketing" ? `${activeBrandLabel} · ${activeRegionLabel}` : tab === "tracking" ? `${trackingMode === "brand" ? brand || "اختر ماركة" : storeId ? stores.find((store) => store.id === storeId)?.name || "محل" : "اختر محلاً"} · ${cycleId === "all" ? "كل الدورات" : selectedCycle?.name || "دورة"}` : `${template?.name || "اختر قالباً"} · ${cycleId === "all" ? "كل الدورات" : selectedCycle?.name || "دورة"}`}</Text></TouchableOpacity>
      {tab !== "marketing" ? <TouchableOpacity onPress={() => setShowProductScope(true)} style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={styles.titleRow}><Text style={[styles.title, { color: colors.foreground }]}>نطاق المنتجات</Text><MaterialIcons name="category" color={colors.primary} size={21} /></View><Text style={[styles.hint, { color: colors.muted }]}>{productIds.length ? `${formatAnalyticsNumber(productIds.length)} منتج محدد` : "كل المنتجات ضمن الاستبيان"}</Text></TouchableOpacity> : null}
      {false && <View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}>
        <View style={styles.titleRow}><Text style={[styles.title, { color: colors.foreground }]}>نطاق التحليل</Text><TouchableOpacity onPress={() => void reload()}><MaterialIcons name="refresh" color={colors.primary} size={20} /></TouchableOpacity></View>
        {tab !== "marketing" ? <>
          <FilterButton label="الاستبيان" value={template?.name || "اختر قالباً"} icon="assignment" colors={colors} onPress={() => setFilter("template")} />
          <View style={styles.pair}><FilterButton label="الدورة" value={cycleId === "all" ? "كل الدورات" : selectedCycle?.name || "دورة"} icon="timeline" colors={colors} onPress={() => setFilter("cycle")} /><FilterButton label="الماركة" value={brand || "كل الماركات"} icon="sell" colors={colors} onPress={() => setFilter("brand")} /></View>
          <View style={styles.pair}><FilterButton label="المنطقة" value={region || "كل المناطق"} icon="map" colors={colors} onPress={() => setFilter("region")} /><FilterButton label="المحل" value={storeId ? stores.find((store) => store.id === storeId)?.name || "محل" : "كل المحلات"} icon="store" colors={colors} onPress={() => setFilter("store")} /></View>
        </> : <>
          <Text style={[styles.hint, { color: colors.muted }]}>يعتمد هذا القسم على الماركات والمناطق فقط، ويمكن اختيار أكثر من قيمة لكل منهما.</Text>
          <View style={styles.pair}><FilterButton label="الماركات" value={activeBrandLabel} icon="sell" colors={colors} onPress={() => setFilter("brand")} /><FilterButton label="المناطق" value={activeRegionLabel} icon="map" colors={colors} onPress={() => setFilter("region")} /></View>
        </>}
      </View>}
      {false && tab !== "marketing" && <View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={styles.titleRow}><Text style={[styles.title, { color: colors.foreground }]}>المنتجات</Text><Text style={[styles.hint, { color: colors.muted }]}>{productIds.length ? `${productIds.length} محدد` : "كل المنتجات"}</Text></View><ScrollView horizontal contentContainerStyle={styles.chips} showsHorizontalScrollIndicator={false}><Chip label="كل المنتجات" active={!productIds.length} colors={colors} onPress={() => setProductIds([])} />{visibleProducts.map((product) => <Chip key={product.id} label={product.name} active={productIds.includes(product.id)} colors={colors} onPress={() => toggleProduct(product.id)} />)}</ScrollView></View>}
      {tab === "marketing" ? <><MarketingAnalyticsChart data={marketing} chartType={settings.chartType} /><MarketingSummary colors={colors} data={marketing} /><MarketingAssetsOverview colors={colors} data={marketing} /></> : <><Summary colors={colors} analytics={displayAnalytics} sourcePresence={sourcePresence} /><DecisionIndicators colors={colors} metrics={decisionMetrics} settings={settings} />{tab === "tracking" ? <><TrackingProfilePanel colors={colors} profile={trackingProfile} /><AnalyticsCategoryCharts analytics={displayAnalytics} scopeLabel={scopeLabel} chartType={settings.chartType} chartOrientation={settings.chartOrientation} selectedSingleCycle={cycleId !== "all"} showValues={settings.showChartValues} showProductNames={settings.showChartProductNames} labelSize={settings.chartLabelSize} rotateProductNames={settings.rotateProductNames} aggregation={settings.categoryAggregation} categoryOrder={templateCategoryOrder} /><TrackingNotes colors={colors} analytics={displayAnalytics} /></> : <>{settings.regionMatrix.enabled ? <>{settings.regionMatrix.categoryMatricesEnabled ? categoryMatrices.map((item) => <AnalyticsRegionMatrix key={item.category} title={`مصفوفة الصنف: ${item.category}`} matrix={item.matrix} settings={settings.regionMatrix} regionOptions={matrixRegionOptions} productOptions={item.products} selectedRegions={matrixRegionNames} selectedProductIds={item.selectedProductIds} onToggleRegion={toggleMatrixRegion} onToggleProduct={toggleMatrixProduct} onClearFilters={() => { setMatrixRegionNames([]); setMatrixProductIds([]); }} />) : <AnalyticsRegionMatrix matrix={regionMatrix} settings={settings.regionMatrix} regionOptions={matrixRegionOptions} productOptions={displayAnalytics.productOptions} selectedRegions={matrixRegionNames} selectedProductIds={matrixProductIds} onToggleRegion={toggleMatrixRegion} onToggleProduct={toggleMatrixProduct} onClearFilters={() => { setMatrixRegionNames([]); setMatrixProductIds([]); }} />}</> : null}<AnalyticsCategoryCharts analytics={displayAnalytics} scopeLabel="نتائج الاستبيان والدورات ضمن المرشحات المختارة" chartType={settings.chartType} chartOrientation={settings.chartOrientation} selectedSingleCycle={cycleId !== "all"} showValues={settings.showChartValues} showProductNames={settings.showChartProductNames} labelSize={settings.chartLabelSize} rotateProductNames={settings.rotateProductNames} aggregation={settings.categoryAggregation} categoryOrder={templateCategoryOrder} /><SurveySeries colors={colors} analytics={displayAnalytics} /></>}</>}
    </ScrollView>
    <AnalyticsScopeModal visible={showScope} title="نطاق التحليل" colors={colors} onClose={() => setShowScope(false)}>{tab === "tracking" ? <><FilterButton label="الاستبيان" value={template?.name || "اختر قالباً"} icon="assignment" colors={colors} onPress={() => setFilter("template")} /><View style={styles.pair}><FilterButton label="الدورة" value={cycleId === "all" ? "كل الدورات" : selectedCycle?.name || "دورة"} icon="timeline" colors={colors} onPress={() => setFilter("cycle")} /><FilterButton label={trackingMode === "brand" ? "الماركة" : "المحل"} value={trackingMode === "brand" ? brand || "اختر ماركة" : storeId ? stores.find((store) => store.id === storeId)?.name || "محل" : "اختر محلاً"} icon={trackingMode === "brand" ? "sell" : "store"} colors={colors} onPress={() => setFilter(trackingMode === "brand" ? "brand" : "store")} /></View></> : tab === "surveys" ? <><FilterButton label="الاستبيان" value={template?.name || "اختر قالباً"} icon="assignment" colors={colors} onPress={() => setFilter("template")} /><View style={styles.pair}><FilterButton label="الدورة" value={cycleId === "all" ? "كل الدورات" : selectedCycle?.name || "دورة"} icon="timeline" colors={colors} onPress={() => setFilter("cycle")} /><FilterButton label="الماركة" value={brand || "كل الماركات"} icon="sell" colors={colors} onPress={() => setFilter("brand")} /></View><View style={styles.pair}><FilterButton label="المنطقة" value={region || "كل المناطق"} icon="map" colors={colors} onPress={() => setFilter("region")} /><FilterButton label="المحل" value={storeId ? stores.find((store) => store.id === storeId)?.name || "محل" : "كل المحلات"} icon="store" colors={colors} onPress={() => setFilter("store")} /></View></> : <><Text style={[styles.hint, { color: colors.muted }]}>يعتمد هذا القسم على الماركات والمناطق فقط، ويمكن اختيار أكثر من قيمة لكل منهما.</Text><View style={styles.pair}><FilterButton label="الماركات" value={activeBrandLabel} icon="sell" colors={colors} onPress={() => setFilter("brand")} /><FilterButton label="المناطق" value={activeRegionLabel} icon="map" colors={colors} onPress={() => setFilter("region")} /></View></>}</AnalyticsScopeModal>
    <AnalyticsProductScopeModal visible={showProductScope} products={allProductOptions} selectedIds={productIds} onToggleProduct={toggleProduct} onSetCategory={toggleProductCategory} onClear={() => setProductIds([])} onClose={() => setShowProductScope(false)} />
    <CenteredSelectionModal filter={filter} colors={colors} templates={templates} cycles={templateCycles} brands={brands} regions={regions} stores={availableStores} selected={{ templateId, cycleId, brand, region, storeId, marketingBrands, marketingRegions }} isMarketing={tab === "marketing"} onTemplate={resetTemplate} onCycle={(value) => { setCycleId(value); setFilter(null); }} onBrand={(value) => { setBrand(value); setProductIds([]); setFilter(null); }} onRegion={resetRegion} onStore={(value) => { setStoreId(value); setFilter(null); }} onMarketingBrand={toggleMarketingBrand} onMarketingRegion={toggleMarketingRegion} onClearMarketingBrands={clearMarketingBrands} onClearMarketingRegions={clearMarketingRegions} onClose={() => setFilter(null)} />
    <AnalyticsSettingsSheet visible={showSettings} settings={settings} matrixCategoryOptions={matrixCategoryOptions} onSave={updateSettings} onClose={() => setShowSettings(false)} />
    <AnalyticsImportModal visible={showExternalImport} colors={colors} packageName={externalPackageName} fileName={externalFileName} hasPayload={Boolean(externalPayload)} isSaving={importingExternal} onClose={() => !importingExternal && setShowExternalImport(false)} onOpenSaved={() => { setShowExternalImport(false); void openExternalPackages(); }} onPickFile={() => void chooseExternalFile()} onChangeName={setExternalPackageName} onSave={() => void importExternalResults()} />
    <ExternalPackagesModal visible={showExternalPackages} colors={colors} items={externalPackages} onClose={() => setShowExternalPackages(false)} onOpen={openExternalPackage} onAnalyzeAll={openCombinedExternalPackages} onLongPress={canDelete ? setPackageToDelete : undefined} />
    <ConfirmDialog visible={Boolean(packageToDelete)} title="حذف تحليل محفوظ" message={packageToDelete ? `سيُحذف «${packageToDelete.name}» وملفه المحلي نهائياً. لا يمكن استعادته.` : ""} confirmText="حذف نهائياً" isDangerous icon="delete-outline" onCancel={() => setPackageToDelete(null)} onConfirm={() => void removeExternalPackage()} />
    <AnalysisFab colors={colors} visible={menuOpen} exporting={exporting} externalMode={Boolean(externalPackageId || combinedExternal)} reportTitle={report.title} canCreate={canCreate} canManage={canManage} canExport={canExport} onToggle={() => setMenuOpen((value) => !value)} onSettings={() => { setMenuOpen(false); setShowSettings(true); }} onImport={() => { setMenuOpen(false); setShowExternalPackages(false); setShowExternalImport(true); }} onSaved={() => void openExternalPackages()} onExport={exportReport} />
  </View>;
}

function FilterButton({ label, value, icon, colors, onPress }: { label: string; value: string; icon: keyof typeof MaterialIcons.glyphMap; colors: Palette; onPress: () => void }) { return <TouchableOpacity onPress={onPress} style={[styles.filter, { backgroundColor: colors.background, borderColor: colors.border }]}><MaterialIcons name={icon} size={18} color={colors.primary} /><View style={styles.filterCopy}><Text style={[styles.filterLabel, { color: colors.muted }]}>{label}</Text><Text numberOfLines={1} style={[styles.filterValue, { color: colors.foreground }]}>{toWesternDigits(value)}</Text></View><MaterialIcons name="expand-more" size={18} color={colors.muted} /></TouchableOpacity>; }
function Chip({ label, active, colors, onPress }: { label: string; active: boolean; colors: Palette; onPress: () => void }) { return <TouchableOpacity onPress={onPress} style={[styles.chip, { backgroundColor: active ? colors.primary : colors.background, borderColor: active ? colors.primary : colors.border }]}><Text style={{ color: active ? "#fff" : colors.muted, fontSize: 11, fontWeight: "800" }}>{toWesternDigits(label)}</Text></TouchableOpacity>; }
function Summary({ analytics, colors, sourcePresence }: { analytics: AdvancedSurveyAnalytics; colors: Palette; sourcePresence: ReturnType<typeof calculateAnalyticsSourcePresenceAverages> }) { return <View style={styles.summaryMetrics}>{[["الدورات", formatAnalyticsNumber(analytics.points.length), "timeline", colors.primary], ["المحلات", formatAnalyticsNumber(analytics.totalStores), "store", colors.success], ["متوسط منتجاتنا", sourcePresence.company === undefined ? "—" : `${sourcePresence.company}%`, "inventory-2", colors.primary], ["متوسط المنافسين", sourcePresence.competitor === undefined ? "—" : `${sourcePresence.competitor}%`, "compare-arrows", colors.warning]].map(([label, value, icon, color]) => <View key={String(label)} style={[styles.summaryMetric, { backgroundColor: colors.surface, borderColor: colors.border }]}><MaterialIcons name={icon as keyof typeof MaterialIcons.glyphMap} color={color as string} size={20} /><Text style={[styles.metricValue, { color: colors.foreground }]}>{value}</Text><Text style={[styles.metricLabel, { color: colors.muted }]}>{label}</Text></View>)}</View>; }
function TrackingModeSelector({ mode, colors, onChange }: { mode: TrackingMode; colors: Palette; onChange: (mode: TrackingMode) => void }) { return <View style={[trackingStyles.modeSelector, { backgroundColor: colors.surface, borderColor: colors.border }]}>{(["brand", "store"] as TrackingMode[]).map((item) => <TouchableOpacity key={item} onPress={() => onChange(item)} style={[trackingStyles.modeOption, { backgroundColor: mode === item ? colors.primary : colors.background, borderColor: mode === item ? colors.primary : colors.border }]}><MaterialIcons name={item === "brand" ? "sell" : "store"} size={18} color={mode === item ? "#fff" : colors.primary} /><Text style={[trackingStyles.modeOptionText, { color: mode === item ? "#fff" : colors.foreground }]}>{item === "brand" ? "تتبع ماركة" : "تتبع محل"}</Text></TouchableOpacity>)}</View>; }
function TrackingProfilePanel({ profile, colors }: { profile: EntityTrackingProfile; colors: Palette }) { const title = profile.kind === "brand" ? `ملف متابعة ماركة: ${profile.name}` : `ملف متابعة محل: ${profile.name}`; const metricItems = [["الزيارات", formatAnalyticsNumber(profile.totalSurveys), "fact-check" as const, colors.primary], ["المحلات", formatAnalyticsNumber(profile.totalStores), "store" as const, colors.success], ["متوسط التواجد", `${profile.averagePresence}%`, "show-chart" as const, colors.warning], ["الأصول المرتبطة", formatAnalyticsNumber(profile.signages.length + profile.stands.length), "campaign" as const, "#7C3AED"]]; return <><View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={styles.titleRow}><Text style={[styles.title, { color: colors.foreground }]}>{title}</Text><MaterialIcons name={profile.kind === "brand" ? "sell" : "storefront"} size={21} color={colors.primary} /></View><View style={styles.summaryMetrics}>{metricItems.map(([label, value, icon, color]) => <View key={String(label)} style={[styles.summaryMetric, { backgroundColor: colors.background, borderColor: colors.border }]}><MaterialIcons name={icon as keyof typeof MaterialIcons.glyphMap} color={color as string} size={19} /><Text style={[styles.metricValue, { color: colors.foreground }]}>{String(value)}</Text><Text style={[styles.metricLabel, { color: colors.muted }]}>{String(label)}</Text></View>)}</View></View><TrackingProductSection title={profile.kind === "brand" ? "منتجات الماركة" : "منتجاتنا في المحل"} icon="inventory-2" products={profile.primaryProducts} colors={colors} /><TrackingProductSection title={profile.kind === "brand" ? "المنتجات المنافسة ضمن الأصناف نفسها" : "منتجات المنافسين في المحل"} icon="compare-arrows" products={profile.competingProducts} colors={colors} /><View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.title, { color: colors.foreground }]}>الفعاليات والأصول المرتبطة</Text><MarketingRow label="الفعاليات" value={formatAnalyticsNumber(profile.events.length)} colors={colors} /><MarketingRow label="اللوحات" value={formatAnalyticsNumber(profile.signages.length)} colors={colors} /><MarketingRow label="الستاندات" value={formatAnalyticsNumber(profile.stands.length)} colors={colors} /><MarketingRow label="الأهداف المرتبطة" value={formatAnalyticsNumber(profile.goals.length)} colors={colors} /><MarketingRow label="تقدم الأهداف" value={profile.goalProgress === undefined ? "غير متاح" : `${profile.goalProgress}%`} colors={colors} /><MarketingRow label="تكلفة الفعاليات" value={`${formatAnalyticsNumber(profile.totalEventCost)} ل.س`} colors={colors} /></View></>; }
function TrackingProductSection({ title, icon, products, colors }: { title: string; icon: keyof typeof MaterialIcons.glyphMap; products: EntityTrackingProfile["productMetrics"]; colors: Palette }) { return <View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={styles.titleRow}><Text style={[styles.title, { color: colors.foreground }]}>{title}</Text><MaterialIcons name={icon} size={20} color={colors.primary} /></View>{products.length ? products.map((product) => <View key={product.productId} style={[styles.productRow, { backgroundColor: colors.background, borderColor: colors.border }]}><View style={[styles.dot, { backgroundColor: product.type === "company" ? colors.primary : colors.warning }]} /><View style={styles.productCopy}><Text style={[styles.productName, { color: colors.foreground }]}>{toWesternDigits(product.productName)}</Text><Text style={[styles.optionalMetrics, { color: colors.muted }]}>{toWesternDigits(`${product.category} · ${product.presentCount}/${product.sampleSize} رصد`)}</Text></View><Text style={[styles.productPercent, { color: product.type === "company" ? colors.primary : colors.warning }]}>{product.presencePercentage}%</Text></View>) : <Empty colors={colors} />}</View>; }
function DecisionIndicators({ colors, metrics, settings }: { colors: Palette; metrics: AnalyticsDecisionMetrics; settings: AnalyticsSettings }) { const items = [
  settings.enabledIndicators.surveyCoverage ? { label: "تغطية المحلات", value: `${metrics.surveyCoverage.percentage}%`, detail: `${formatAnalyticsNumber(metrics.surveyCoverage.surveyedStores)} من ${formatAnalyticsNumber(metrics.surveyCoverage.eligibleStores)} محل`, icon: "map" as const, color: colors.primary } : null,
  settings.enabledIndicators.opportunityList ? { label: "فرص التحسين", value: formatAnalyticsNumber(metrics.opportunities.length), detail: metrics.opportunities.slice(0, 2).map((item) => item.productName).join("، ") || "لا توجد فرص", icon: "trending-down" as const, color: colors.warning } : null,
  settings.enabledIndicators.cycleChange ? { label: "تراجع بين الدورات", value: formatAnalyticsNumber(metrics.cycleChanges.filter((item) => item.previousPresence !== undefined && item.change < 0).length), detail: "منتجات تحتاج متابعة", icon: "show-chart" as const, color: colors.error } : null,
  settings.enabledIndicators.sampleConfidence ? { label: "عينات منخفضة", value: formatAnalyticsNumber(metrics.sampleConfidence.filter((item) => item.confidence === "low").length), detail: `أقل من ${formatAnalyticsNumber(settings.lowSampleThreshold)} رصد`, icon: "verified-user" as const, color: "#7C3AED" } : null,
].filter(Boolean) as Array<{ label: string; value: string; detail: string; icon: keyof typeof MaterialIcons.glyphMap; color: string }>;
  if (!items.length) return null;
  return <View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={styles.titleRow}><Text style={[styles.title, { color: colors.foreground }]}>مؤشرات القرار</Text><MaterialIcons name="insights" size={20} color={colors.primary} /></View><View style={decisionStyles.grid}>{items.map((item) => <View key={item.label} style={[decisionStyles.item, { backgroundColor: item.color + "10", borderColor: item.color + "35" }]}><MaterialIcons name={item.icon} size={18} color={item.color} /><View style={decisionStyles.copy}><Text style={[decisionStyles.value, { color: item.color }]}>{item.value}</Text><Text style={[decisionStyles.label, { color: colors.foreground }]}>{item.label}</Text><Text numberOfLines={1} style={[decisionStyles.detail, { color: colors.muted }]}>{item.detail}</Text></View></View>)}</View>{settings.enabledIndicators.uniqueStorePresence ? <Text style={[styles.hint, { color: colors.muted }]}>تواجد المحلات الفريدة يحسب من أحدث زيارة لكل محل ضمن النطاق.</Text> : null}</View>; }
function SurveySeries({ analytics, colors }: { analytics: AdvancedSurveyAnalytics; colors: Palette }) { return <View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.title, { color: colors.foreground }]}>تفاصيل المنتجات حسب الدورة</Text>{analytics.points.length ? analytics.points.map((point) => <View key={point.cycleId} style={[styles.cycle, { borderColor: colors.border }]}><Text style={[styles.cycleTitle, { color: colors.foreground }]}>{toWesternDigits(point.cycleName)}</Text><Text style={[styles.hint, { color: colors.muted }]}>{formatAnalyticsNumber(point.storeCount)} محل · {formatAnalyticsNumber(point.surveyCount)} نتيجة</Text>{point.products.map((product) => <View key={product.productId} style={[styles.productRow, { backgroundColor: colors.background, borderColor: colors.border }]}><View style={[styles.dot, { backgroundColor: product.color }]} /><View style={styles.productCopy}><Text style={[styles.productName, { color: colors.foreground }]}>{toWesternDigits(product.productName)}</Text>{product.averageShelfPercentage !== undefined || product.averagePrice !== undefined ? <Text style={[styles.optionalMetrics, { color: colors.muted }]}>{product.averageShelfPercentage !== undefined ? `متوسط الظهور ${product.averageShelfPercentage}%` : ""}{product.averageShelfPercentage !== undefined && product.averagePrice !== undefined ? " · " : ""}{product.averagePrice !== undefined ? `متوسط السعر ${formatAnalyticsNumber(product.averagePrice)} ل.س` : ""}</Text> : null}</View><Text style={[styles.productPercent, { color: product.color }]}>{product.presencePercentage}%</Text></View>)}</View>) : <Empty colors={colors} />}</View>; }
function TrackingNotes({ analytics, colors }: { analytics: AdvancedSurveyAnalytics; colors: Palette }) { return <View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={styles.titleRow}><Text style={[styles.title, { color: colors.foreground }]}>التعليقات المصنفة</Text><Text style={[styles.hint, { color: colors.muted }]}>{formatAnalyticsNumber(analytics.notes.length)} تعليق</Text></View><View style={styles.noteCounters}>{Object.entries(analytics.noteCounts).map(([type, count]) => { const style = NOTE_STYLES[type as TrackingNote["type"]]; return <View key={type} style={[styles.noteCounter, { backgroundColor: style.color + "14" }]}><MaterialIcons name={style.icon} size={14} color={style.color} /><Text style={[styles.noteCounterText, { color: style.color }]}>{style.label} {formatAnalyticsNumber(count)}</Text></View>; })}</View>{analytics.notes.length ? analytics.notes.map((note) => { const style = NOTE_STYLES[note.type]; return <View key={note.id} style={[styles.noteItem, { backgroundColor: colors.background, borderColor: colors.border }]}><View style={[styles.noteIcon, { backgroundColor: style.color + "18" }]}><MaterialIcons name={style.icon} size={18} color={style.color} /></View><View style={styles.noteCopy}><View style={styles.noteMeta}><Text style={[styles.noteStore, { color: colors.foreground }]}>{toWesternDigits(note.storeName)}</Text><Text style={[styles.noteType, { color: style.color }]}>{style.label}</Text></View><Text style={[styles.noteText, { color: colors.foreground }]}>{toWesternDigits(note.text)}</Text><Text style={[styles.noteDate, { color: colors.muted }]}>{toWesternDigits(note.cycleName)} · {formatAnalyticsDate(note.surveyDate)}</Text></View></View>; }) : <Empty colors={colors} />}</View>; }
function MarketingSummary({ data, colors }: { data: ReturnType<typeof calculateMarketingAnalytics>; colors: Palette }) { const goalLabel = data.goalProgress === undefined ? "لا يوجد هدف مرتبط بالماركات المحددة" : `${data.goalProgress}%`; return <><View style={styles.metrics}>{[["الفعاليات", formatAnalyticsNumber(data.events.length), "event", colors.primary], ["التكلفة", `${formatAnalyticsNumber(data.totalCost)} ل.س`, "payments", colors.warning], ["تقدم الأهداف", goalLabel, "flag", colors.success]].map(([label, value, icon, color]) => <View key={String(label)} style={[styles.metric, { backgroundColor: colors.surface, borderColor: colors.border }]}><MaterialIcons name={icon as keyof typeof MaterialIcons.glyphMap} color={color as string} size={20} /><Text numberOfLines={1} style={[styles.metricValue, { color: colors.foreground, fontSize: String(value).length > 9 ? 12 : 17 }]}>{String(value)}</Text><Text style={[styles.metricLabel, { color: colors.muted }]}>{label}</Text></View>)}</View><View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.title, { color: colors.foreground }]}>الفعاليات والأهداف المرتبطة</Text><MarketingRow label="إجمالي الميزانية" value={`${formatAnalyticsNumber(data.totalBudget)} ل.س`} colors={colors} /><MarketingRow label="التكلفة الفعلية" value={`${formatAnalyticsNumber(data.totalCost)} ل.س`} colors={colors} /><MarketingRow label="الأهداف المرتبطة" value={formatAnalyticsNumber(data.goals.length)} colors={colors} /><MarketingRow label="نسبة الإنجاز المجمعة" value={data.goalProgress === undefined ? "غير متاح" : `${data.goalProgress}%`} colors={colors} /></View><View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><Text style={[styles.title, { color: colors.foreground }]}>اللوحات والستاندات</Text><MarketingRow label="اللوحات النشطة" value={formatAnalyticsNumber(data.activeSignages)} colors={colors} /><MarketingRow label="إجمالي اللوحات" value={formatAnalyticsNumber(data.signages.length)} colors={colors} /><MarketingRow label="الستاندات بحالة جيدة" value={formatAnalyticsNumber(data.activeStands)} colors={colors} /><MarketingRow label="إجمالي الستاندات" value={formatAnalyticsNumber(data.stands.length)} colors={colors} /></View></>; }
function MarketingAssetsOverview({ data, colors }: { data: ReturnType<typeof calculateMarketingAnalytics>; colors: Palette }) { const eventNames = data.events.map((event) => event.name || event.brandName || "فعالية").slice(0, 4); const boardBrands = data.signages.map((item) => item.brand || "لوحة").slice(0, 4); const standBrands = data.stands.map((item) => item.brand || "ستاند").slice(0, 4); return <View style={[styles.card, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={styles.titleRow}><Text style={[styles.title, { color: colors.foreground }]}>تفاصيل الفعاليات والأصول ضمن النطاق</Text><MaterialIcons name="campaign" size={20} color={colors.primary} /></View><AssetListRow icon="event" label="الفعاليات" items={eventNames} colors={colors} /><AssetListRow icon="view-carousel" label="اللوحات" items={boardBrands} colors={colors} /><AssetListRow icon="storefront" label="الستاندات" items={standBrands} colors={colors} /></View>; }
